        spd: +p.spd >= 0 && +p.spd < 70 ? Math.round(+p.spd * 10) / 10 : null, // metres per second
        hdg: +p.hdg >= 0 && +p.hdg <= 360 ? Math.round(+p.hdg) : null,
        t: now(),
        ms,
        inArea: C.zcBox(lat, lng),
