      h.ntf(
        dr.em,
        'Vehicle assigned',
        `You are now assigned to ${vehName(v)}. Set yourself to Available to receive bookings.`
      );
      h.ntf(v.owner, 'Driver assigned', `${dr.name} now drives ${vehName(v)}.`);
