'use strict';
/* Self-drive rentals (customer side) and incident reports. */
const C = require('./constants');
const { now, r2, rid, str, img, ok, no, peso, todayPH, sha256 } = require('../util');

const FUEL = ['Full', '3/4', '1/2', '1/4', 'Empty'];
const nm = x =>
  String(x || '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
