        id: rid('RN'),
        cu: me.em,
        veh: v.id,
        vid: v.id,
        vt: v.type,
        owner: v.owner,
        vn: [v.brand, v.model].filter(Boolean).join(' '),
        day: +v.rent.day,
        s,
        e,
        days,
        tot: r2(days * v.rent.day),
        dep: +v.rent.dep || C.DEP,
        st: 'Pending',
        pu,
        rt,
        lic,
        exp,
        ip: img(p.ip),
        lp: img(p.lp),
